import javax.xml.bind.JAXB
import javax.xml.transform.Source

class Bad {
    fun <T> unmarshal(src: Source, clazz: Class<T>): T = JAXB.unmarshal(src, clazz) // bad
}

import javax.xml.bind.JAXB
import javax.xml.transform.Source

fun <T> unmarshalAll(sources: List<Source>, clazz: Class<T>): List<T> =
    sources.map {
        JAXB.unmarshal(it, clazz) // bad - recreates JAXBContext per call
    }

import javax.xml.bind.JAXBContext

class Good<T>(clazz: Class<T>) {
    private val ctx = JAXBContext.newInstance(clazz) // ok: created once

    fun unmarshal(src: javax.xml.transform.Source): T =
        ctx.createUnmarshaller().unmarshal(src) as T
}
